import math

def build_agent(sandbox):
    # Create a wide, flat hull for buoyancy and stability
    hull = sandbox.add_beam(x=5.0, y=1.0, width=3.0, height=2.0, density=20.0)

    # Add multiple paddles for propulsion, angled to optimize water interaction
    paddle_width = 0.5
    paddle_height = 1.0
    paddle_angle = math.radians(30)  # Slightly angled upward to optimize water interaction

    # Add 12 paddles distributed along the hull for balanced propulsion
    for i in range(12):
        x_pos = 4.0 + i * 0.3  # Distribute paddles across the hull from x=4.0 to 7.5
        paddle = sandbox.add_beam(x=x_pos, y=1.0, width=paddle_width, height=paddle_height, angle=paddle_angle, density=5.0)
        sandbox.add_joint(hull, paddle, (x_pos, 1.0), type='rigid')

    return hull

def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    # Stop when reaching target
    if front_x >= target_x + 0.1:
        for b in sandbox.bodies:
            if b.active:
                sandbox.apply_force(b, 0.0, 0.0, step_count=step_count)
        return

    # Calculate thrust based on environment
    THRUST_F = 520.0  # Max thrust per component
    LIFT_F = 520.0    # Maximum lift force per component

    # Check if in deep channel (reduced buoyancy)
    in_danger_zone = (16.5 <= front_x <= 19.5)

    # Apply thrust to paddles every 200 steps
    if step_count % 200 == 0:
        # Check if the vehicle is in the deep channel and adjust force accordingly
        if in_danger_zone:
            # Apply lift force to maintain buoyancy in deep channel
            for b in sandbox.bodies:
                if b is not agent_body:  # Apply to paddles
                    sandbox.apply_force(b, 0.0, LIFT_F, step_count=step_count)
        else:
            # Apply forward force to all paddles
            for b in sandbox.bodies:
                if b is not agent_body:  # Apply to paddles
                    # Calculate the thrust based on velocity
                    vx = b.linearVelocity.x
                    if vx < 0:
                        # If moving backward, apply maximum thrust to overcome resistance
                        fx = THRUST_F
                    else:
                        # Adjust thrust based on velocity
                        if vx > 1.8:
                            fx = THRUST_F * 0.1
                        elif vx > 1.0:
                            fx = THRUST_F * 0.4
                        else:
                            fx = THRUST_F
                    sandbox.apply_force(b, fx, 0.0, step_count=step_count)

